from pathlib import Path
import numpy as np,json,wave,sys,hashlib
folder=Path(sys.argv[1]);rows=[]
for d in json.loads((folder/'inputs.json').read_text()):
 p=Path(d['filename']);size=p.stat().st_size
 if p.suffix=='.wav':
  with wave.open(str(p)) as f:
   assert f.getframerate()==22050 and f.getnchannels()==1 and f.getsampwidth()==2
   x=np.frombuffer(f.readframes(f.getnframes()),dtype='<i2').astype(float)/32767
 else:x=np.fromfile(p,dtype='<f4').astype(float)
 peak=float(np.max(np.abs(x)));rms=float(np.sqrt(np.mean(x*x)));dc=float(np.mean(x));boundary=float(abs(x[-1]-x[0]));spectrum=np.abs(np.fft.rfft(x))**2;freq=np.fft.rfftfreq(len(x),1/22050);hf=float(spectrum[freq>6000].sum()/max(1e-20,spectrum.sum()));nonzero=np.flatnonzero(abs(x)>.0001)
 result={**d,'duration':len(x)/22050,'peak':peak,'rms':rms,'dcOffset':dc,'boundaryDiscontinuity':boundary,'energyAbove6kHzFraction':hf,'clippedSamples':int((abs(x)>=1).sum()),'silenceStartSeconds':float(nonzero[0]/22050) if len(nonzero) else len(x)/22050,'silenceEndSeconds':float((len(x)-1-nonzero[-1])/22050) if len(nonzero) else len(x)/22050,'fileBytes':size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
 assert peak<.45 and abs(dc)<.001 and hf<.002,result
 if d['loop']:assert boundary<.0002,result
 if p.suffix!='.wav':result['filename']=d['runtime'];result['fileBytes']=0;result.pop('runtime',None)
 rows.append(result)
out=Path('docs/verification/story-audio');out.mkdir(parents=True,exist_ok=True);(out/'audio-report.json').write_text(json.dumps({'sampleRate':22050,'result':'PASS','subjectiveListening':'Human listening approval still required; waveform checks cannot establish pleasantness.','rows':rows},indent=2)+'\n')
md=['# Original audio inventory and waveform audit','', 'All six scores are newly authored in src/audio/score.js and rendered to mono 16-bit PCM by scripts/generate-audio.mjs. No external recording, commercial-game melody, preset sample, generative audio service or remote asset was used. Bass is a finite triangle-like harmonic sum; gentle pulse and bell voices use sine harmonics. Sparse low-frequency taps replace noise percussion. Music starts/ends with rounded envelopes. Effects and three ambience textures are synthesized once and cached after unlock.','', 'Human listening approval remains required. Numeric checks cannot establish that a melody is pleasant, non-tiring or subjectively seamless. Physical-device audio output is unverified.','', '| Name / event | Seconds | Peak | RMS | DC offset | Loop boundary | Above 6 kHz | Loop | Runtime / source |','| --- | ---: | ---: | ---: | ---: | ---: | ---: | --- | --- |']
for r in rows:md.append(f"| {r['name']} | {r['duration']:.2f} | {r['peak']:.4f} | {r['rms']:.4f} | {r['dcOffset']:.6f} | {r['boundaryDiscontinuity']:.6f} | {r['energyAbove6kHzFraction']:.6%} | {'yes' if r['loop'] else 'no'} | {r['filename']} |")
md+=['',f'{len(rows)} entries checked. Zero clipped samples. Six WAV files total {sum(r["fileBytes"] for r in rows):,} bytes. Effects have finite duration, softly varied pitch/level and a six-voice cap; the completion cue has one separate bounded music voice. No oscillator, interval or audio timer survives scene rebuilds.','', 'Source rights: original Simple Life work authored with OpenAI Codex assistance, within the user-authorized competition project. This is not a claim of exclusive copyright, human composition or completed human review. Retained external artwork keeps its separate creator licences.','', 'Reproduce: node scripts/generate-audio.mjs; node scripts/audit-audio.mjs. Debug effects use temporary raw samples outside production. Production ships only the six named WAVs under the explicit allowlist.']
md+=['','The removed ForestAmbience used a shared two-second random-noise buffer continuously through low-pass wind, high-pass river and a 4.2 kHz insect band, with occasional 1.8–3.4 kHz oscillator chirps and no music. That tonal absence, short noise repetition and emphasized upper frequencies plausibly explain the reported static-like character; this is an inference from source, not a human listening diagnosis. The replacement uses no white-noise buffer or random high-frequency melody. Quiet low-frequency textures, sparse bounded calls and authored tonal phrases supply the foundation.\n\nImportant project/request/key/pickup/restoration feedback can wait at most 250 ms in a bounded four-entry queue if a UI frame is busy. It still obeys the two-starts-per-frame/six-voice limit and is discarded on expiry, New Game/Continue reset, Title or destruction. Rapid input cannot accumulate an unbounded queue.']
Path('docs/AUDIO_SOURCES.md').write_text('\n'.join(md)+'\n');print(f'{len(rows)} audio entries: no clipping; DC, high-frequency and loop checks PASS.')
